#!/usr/bin/env node
/**
 * Full read of a Discord channel (paginate until empty / age cap).
 * Usage: node scripts/_tmp-full-read-channel.mjs [channelId]
 */
import { loadEnv, botToken } from "../src/config.mjs";
import { makeFetchJson } from "../src/discordApi.mjs";

await loadEnv();
const channelId = process.argv[2] || "1532929974154166522";
const fetchJson = makeFetchJson(botToken());

const MAX = Number(process.env.FULL_READ_MAX || 500);
const all = [];
let before;
while (all.length < MAX) {
  const qs = new URLSearchParams({ limit: "100" });
  if (before) qs.set("before", before);
  const batch = await fetchJson(`/channels/${channelId}/messages?${qs}`);
  if (!Array.isArray(batch) || !batch.length) break;
  all.push(...batch);
  before = batch[batch.length - 1].id;
  if (batch.length < 100) break;
}

// oldest → newest for reading
all.reverse();

function ts(id) {
  try {
    const snow = BigInt(id);
    const ms = Number((snow >> 22n) + 1420070400000n);
    return new Date(ms).toISOString().replace("T", " ").replace(/\.\d+Z$/, "Z");
  } catch {
    return "?";
  }
}

console.log(`channel ${channelId} — ${all.length} messages (oldest→newest)\n`);
for (const m of all) {
  const who = m.author?.global_name || m.author?.username || "?";
  const bot = m.author?.bot ? " [BOT]" : "";
  const refs = m.message_reference?.message_id
    ? ` (reply→${m.message_reference.message_id})`
    : "";
  const content = String(m.content || "")
    .replace(/\r\n/g, "\n")
    .trim();
  const attach =
    Array.isArray(m.attachments) && m.attachments.length
      ? `\n  [attachments: ${m.attachments.map((a) => a.filename || a.url).join(", ")}]`
      : "";
  const embeds =
    Array.isArray(m.embeds) && m.embeds.length
      ? `\n  [embeds: ${m.embeds.length} — ${(m.embeds[0]?.title || m.embeds[0]?.description || "").toString().slice(0, 80)}]`
      : "";
  console.log(`--- ${ts(m.id)} | ${m.id} | ${who}${bot}${refs}`);
  console.log(content || "(empty)");
  if (attach) console.log(attach.trimEnd());
  if (embeds) console.log(embeds.trimEnd());
  console.log("");
}

