function pickPowerWatts(data) {
  if (!data || typeof data !== "object") return { inW: null, outW: null, solarW: null };
  /**
   * Prefer first *positive* watts among keys. EcoFlow often reports a present
   * zero (e.g. inv.inputWatts=0) before the real path (mppt.inWatts=54 on River).
   * Fall back to zero only if every candidate is zero/missing.
   */
  const getPreferPositive = (...keys) => {
    let zero = null;
    for (const k of keys) {
      if (data[k] == null || Number.isNaN(Number(data[k]))) continue;
      const val = Number(data[k]);
      const hit = { key: k, val };
      if (toWatts(val, k) > 0) return hit;
      if (!zero) zero = hit;
    }
    return zero;
  };
  // Aggregate PD sums first; River often only fills mppt / inv.
  const inp = getPreferPositive(
    "pd.wattsInSum",
    "mppt.inWatts",
    "inv.inputWatts",
    "pd.wattsInSum_mw",
  );
  const out = getPreferPositive(
    "pd.wattsOutSum",
    "inv.outputWatts",
    "pd.wattsOutSum_mw",
  );
  const solar = getPreferPositive(
    "mppt.inWatts",
    "mppt.pv1InWatts",
    "mppt.pv2InWatts",
  );
  return {
    inW: inp ? toWatts(inp.val, inp.key) : null,
    outW: out ? toWatts(out.val, out.key) : null,
    solarW: solar ? toWatts(solar.val, solar.key) : null,
  };
}

