#!/usr/bin/env node
/**
 * #solar-server: pin full ops description + reply to kWh/gold asks.
 */
import { loadEnv, botToken } from "../src/config.mjs";
import { makeFetchJson, postMessage } from "../src/discordApi.mjs";
import { postAvaDiscord } from "../src/avaPost.mjs";
import {
  SOLAR_OPS_DISCORD_CHANNEL_ID,
  SOLAR_LINKS,
  SOLAR_PAGE_OFFLINE_RULE,
  SOLAR_LABEL_RULE,
} from "../src/solarLinks.mjs";
import { loadEcoSnapshot, refreshEcoFlow } from "../src/ecoflow.mjs";
import { loadSolarProfile } from "../src/solarProfile.mjs";
import { computeSolarMiningMultiplier } from "../src/solarMiningMultiplier.mjs";

await loadEnv();
const fetchJson = makeFetchJson(botToken());
const ch = SOLAR_OPS_DISCORD_CHANNEL_ID;

await refreshEcoFlow({ force: true }).catch(() => {});
const snap = loadEcoSnapshot();
const solar = loadSolarProfile();
const bank = snap?.batteryPct ?? null;
const mult = computeSolarMiningMultiplier(bank, true);

const pinBody = [
  "**HI Pacific Solar Root Server — operations pin**",
  "",
  "**What this is**",
  "Ava's dig brain + EcoFlow telemetry host. Public label only — never the city. Uplink: **Starlink + solar**. Endgame: off-grid data center (watts in → RootMC out).",
  "",
  "**Array / bank**",
  `- **${solar?.panels?.count ?? 10} panels** / **${solar?.panels?.circuits ?? 2} circuits** (profile 5+5; field split River2/Delta4 or combine-to-6 when stamped)`,
  "- On-circuit: **Delta 2** `R331ZAB5SG6S2858` + **River 2 Pro** `R621ZA16XH6K1155`",
  "- Delta 2-B removed. Poll ~60s. Live = device-list online **and** sample ≤3m.",
  "",
  "**Labels (locked)**",
  `- **Solar** = panel **input watts** (W). ${SOLAR_LABEL_RULE}`,
  "- **Energy today** = Wh / **kWh estimate** from minute watts — never called \"solar\".",
  "- Pack **in/out** = charge into / load leaving each EcoFlow.",
  "",
  "**Gold mining multiplier**",
  `- Formula: **\`1 + (bankSOC / 100)\`** while host+Eco live. Example: bank **${bank ?? "?"}%** → **${mult}×** (base 1.0 + ${(bank ?? 0) / 100}).`,
  "- Higher bank SOC → more Gold when mining. Host/Eco offline or stale → **1.0×**.",
  "- API: https://api.rootmc.net/api/rootmc/solar-mining-multiplier",
  "",
  "**How to read**",
  `- Board: ${SOLAR_LINKS.solar}`,
  `- Website: ${SOLAR_LINKS.website}`,
  `- Discord \`/solar\` (any channel) or in-game \`/solar\` (Root-Ava-Core)`,
  `- This channel: solar server ops only`,
  "",
  `**${SOLAR_PAGE_OFFLINE_RULE}**`,
  "",
  "Day cycles: midnight close + morning open reports (HST). Don't mix prior-day buckets into today's live board.",
  "",
  "— Ava",
].join("\n");

const pinMsg = await postAvaDiscord({
  channelId: ch,
  content: pinBody,
  refId: "1533915486662824008",
  kind: "solar_ops_pin",
  source: "solar-server-channel-setup",
});
console.log("pin candidate", pinMsg?.id);

if (pinMsg?.id) {
  try {
    await fetchJson(`/channels/${ch}/pins/${pinMsg.id}`, { method: "PUT" });
    console.log("pinned ok");
  } catch (err) {
    console.warn("pin failed:", err.message);
  }
}

const kwhReply = [
  "locked — you're right.",
  "",
  "**Solar** = panel **input** (W) on the device table + \"Solar input\" KPI.",
  "**Energy today** = Wh / **kWh estimate** from minute watts — no longer labeled \"Solar Wh\".",
  "",
  "Device headers now: **Solar in** · **Pack in** · **Out**.",
  "Refresh https://ava.rootmc.net/solar — labels should match.",
].join("\n");

