#!/usr/bin/env node
/**
 * Scan all Ava watch channels for unreplied @Ava / root asks needing action.
 */
import { loadEnv, botToken, DEFAULT_WATCH_CHANNELS, AVA_CHANNELS, AVA_BOT_APP_ID } from "../src/config.mjs";
import { makeFetchJson } from "../src/discordApi.mjs";

await loadEnv();
const fetchJson = makeFetchJson(botToken());
const AVA = String(AVA_BOT_APP_ID || "1532751879875072070");
const ALEX = "1497037418979786823";
const MELEE = "154446475789729792";

const channels = new Set([
  ...DEFAULT_WATCH_CHANNELS,
  ...Object.values(AVA_CHANNELS || {})
    .filter((v) => /^\d{15,}$/.test(String(v)))
    .map(String),
]);

const names = Object.fromEntries(
  Object.entries(AVA_CHANNELS || {}).map(([k, v]) => [String(v), k]),
);

const open = [];
for (const ch of channels) {
  let msgs;
  try {
    msgs = await fetchJson(`/channels/${ch}/messages?limit=40`);
  } catch (err) {
    console.warn("skip", ch, err.message.slice(0, 80));
    continue;
  }
  if (!Array.isArray(msgs) || !msgs.length) continue;

  // newest first from API
  for (let i = 0; i < msgs.length; i++) {
    const m = msgs[i];
    if (m.author?.bot) continue;
    const text = String(m.content || "");
    const mentionsAva =
      text.includes(`<@${AVA}>`) ||
      text.includes(`<@!${AVA}>`) ||
      /\bava\b/i.test(text);
    const isStaff = m.author?.id === ALEX || m.author?.id === MELEE;
    const looksAsk =
      mentionsAva ||
      (isStaff &&
        (/\?/.test(text) ||
          /\b(please|fix|ensure|do |make |add |post |pin |read |check |update|implement)\b/i.test(
            text,
          )));
    if (!looksAsk) continue;

    // Has Ava already replied after this (newer messages = lower index)?
    let avaReplied = false;
    for (let j = 0; j < i; j++) {
      const n = msgs[j];
      if (n.author?.id === AVA || n.author?.username === "Ava Ivy") {
        if (
          n.message_reference?.message_id === m.id ||
          BigInt(n.id) > BigInt(m.id)
        ) {
          // if there's any Ava message after this one in channel, soft-count as caught
          // Prefer reference match
          if (n.message_reference?.message_id === m.id) {
            avaReplied = true;
            break;
          }
        }
      }
    }
    // stricter: only count direct reply or next Ava within 5 msgs after
    let direct = false;
    for (let j = 0; j < i; j++) {
      const n = msgs[j];
      if (
        (n.author?.id === AVA || n.author?.username === "Ava Ivy") &&
        n.message_reference?.message_id === m.id
      ) {
        direct = true;
        break;
      }
    }
    // also: Ava message immediately after (index i-1 if exists? API is newest first so i-1 is newer)
    let nearby = false;
    for (let j = Math.max(0, i - 6); j < i; j++) {
      const n = msgs[j];
      if (n.author?.id === AVA || n.author?.username === "Ava Ivy") {
        nearby = true;
        break;
      }
    }

    const stall =
      /Root Server and dream state are both dark|queued this for when|still digging|wait I need the real answer|same answer as last - skipping|okok hold on|okaay searching|gimme a sec|files first/i.test(
        text,
      );

    if (direct) continue;
    if (nearby && !mentionsAva && text.length < 40) continue;

    const snow = BigInt(m.id);
    const ms = Number((snow >> 22n) + 1420070400000n);
    open.push({
      channelId: ch,
      channel: names[ch] || ch,
      id: m.id,
      when: new Date(ms).toISOString(),
      author: m.author?.global_name || m.author?.username,
      authorId: m.author?.id,
      content: text.slice(0, 280).replace(/\n/g, " / "),
      mentionsAva,
      nearbyAva: nearby,
      stall,
    });
  }
}

// Also flag recent Ava stall lines that never got a real follow-up
const stalls = [];
for (const ch of channels) {
  let msgs;
  try {
    msgs = await fetchJson(`/channels/${ch}/messages?limit=25`);
  } catch {
    continue;
  }
  for (let i = 0; i < (msgs || []).length; i++) {
    const m = msgs[i];
    if (!(m.author?.id === AVA || m.author?.username === "Ava Ivy")) continue;
    const text = String(m.content || "");
    if (
      !/Root Server and dream state are both dark|queued this for when|still digging|wait I need the real answer|same answer as last - skipping the redo/i.test(
        text,
      )
    ) {
      continue;
    }
    // if newer real Ava reply to same ref exists, skip
    const ref = m.message_reference?.message_id;
    let fixed = false;
    for (let j = 0; j < i; j++) {
      const n = msgs[j];
      if (!(n.author?.id === AVA || n.author?.username === "Ava Ivy")) continue;
      const t = String(n.content || "");
      if (
        /Root Server and dream state are both dark|queued this|still digging|wait I need|skipping the redo|okok hold|okaay searching|gimme a sec/i.test(
          t,
        )
      ) {
        continue;
      }
      if (!ref || n.message_reference?.message_id === ref || BigInt(n.id) > BigInt(m.id)) {
        fixed = true;
        break;
      }
    }
    if (!fixed) {
      stalls.push({
        channelId: ch,
        channel: names[ch] || ch,
        id: m.id,
        ref,
        content: text.slice(0, 160).replace(/\n/g, " / "),
      });
    }
  }
}

console.log(JSON.stringify({ openCount: open.length, open, stallCount: stalls.length, stalls }, null, 2));

