function Log($m){ $line = "$(Get-Date -Format o) $m"; Add-Content $log $line; Write-Host $line }
"" | Set-Content $log
$iso = "D:\ubuntu-26.04-desktop-amd64.iso"
$diskNum = 3
$phys = "\\.\PhysicalDrive$diskNum"

Log "ISO=$iso size=$((Get-Item $iso).Length)"
$disk = Get-Disk -Number $diskNum
if ($disk.BusType -ne "USB") { throw "Not USB" }
